/**
 * The HTTP API (decision 0006): one endpoint per catalog operation, generated by `operationsGroup`,
 * and the endpoints only the apps need, declared in `AppGroup`. The server implements it and the
 * browser's client is typed from it; neither path nor body is written twice.
 */
import { Schema } from "effect";
import {
  HttpApi,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiMiddleware,
  HttpApiSchema,
} from "effect/http-api";
import { catalog, FileSuccess, pathParams, type Operation } from "./catalog.ts";
import {
  AttachmentTooLarge,
  FixResult,
  FolderListing,
  InvalidRequest,
  ReorderStatusesInput,
  StatusDefinition,
  StorageError,
  TaskNotFound,
  WorkspaceChange,
  WorkspaceInfo,
  WorkspaceKey,
  WorkspaceNotFound,
  WorkspaceSnapshot,
  wireError,
  wireErrorsOf,
  type WireError,
} from "./domain.ts";
import { MAX_ATTACHMENT_BYTES } from "./rules.ts";

type PathParamNames<Path extends string> = Path extends `${string}:${infer Name}/${infer Rest}`
  ? Name | PathParamNames<`/${Rest}`>
  : Path extends `${string}:${infer Name}`
    ? Name
    : never;

type ParamsOf<Op extends Operation> = [PathParamNames<Op["http"]["path"]>] extends [never]
  ? never
  : Schema.Struct<{ readonly [K in PathParamNames<Op["http"]["path"]>]: Schema.String }>;

type RestOf<Op extends Operation> =
  Omit<Op["input"]["fields"], PathParamNames<Op["http"]["path"]>> extends infer Rest extends
    Schema.Struct.Fields
    ? [keyof Rest] extends [never]
      ? never
      : Schema.Struct<Rest>
    : never;

/** The endpoint `operationEndpoint` makes for one catalog entry, as a type the client reads. */
export type OperationEndpoint<
  Name extends string,
  Op extends Operation,
> = HttpApiEndpoint.HttpApiEndpoint<
  Name,
  Op["http"]["method"],
  Op["http"]["path"],
  ParamsOf<Op>,
  Op["http"]["method"] extends "GET" ? RestOf<Op> : never,
  Op["http"]["method"] extends "GET" ? never : RestOf<Op>,
  never,
  Op["success"] extends Schema.Top ? Op["success"] : HttpApiSchema.StreamUint8Array,
  WireError<Op["error"]>
>;

const RegisteredWorkspace = Schema.String.annotate({ description: "Registered workspace id" });

/**
 * One operation as an endpoint: each `:name` in its path is the input field `name`, required here
 * even where MCP may omit it; the other fields are the query of a `GET` and the JSON body otherwise.
 */
const operationEndpoint = (name: string, operation: Operation) => {
  const inPath = pathParams(operation.http);
  const params = Object.fromEntries(
    inPath.map((key) => {
      const field = operation.input.fields[key]!;
      if (key === "workspace") return [key, RegisteredWorkspace];
      return [key, field.ast.context?.isOptional === true ? Schema.String : field];
    }),
  );
  const rest = Object.entries(operation.input.fields).filter(([key]) => !inPath.includes(key));
  const fields = rest.length === 0 ? undefined : Schema.Struct(Object.fromEntries(rest));
  const make = HttpApiEndpoint.make(operation.http.method) as unknown as (
    name: string,
    path: string,
    options: object,
  ) => HttpApiEndpoint.Top;
  return make(name, operation.http.path, {
    ...(inPath.length === 0 ? {} : { params }),
    ...(fields === undefined
      ? {}
      : operation.http.method === "GET"
        ? { query: fields }
        : { payload: fields }),
    success:
      operation.success === FileSuccess ? HttpApiSchema.StreamUint8Array() : operation.success,
    error: wireErrorsOf(operation.error),
  });
};

/** The endpoints of a catalog's operations, by name. */
export type OperationEndpoints<Ops extends Record<string, Operation>> = {
  readonly [Name in keyof Ops & string]: OperationEndpoint<Name, Ops[Name]>;
}[keyof Ops & string];

/** Every operation of a catalog as an endpoint at its `http` path (decision 0005). */
export const operationsGroup = <const Ops extends Record<string, Operation>>(
  operations: Ops,
): HttpApiGroup.HttpApiGroup<"operations", OperationEndpoints<Ops>> =>
  (HttpApiGroup.make("operations").add as (...endpoints: Array<HttpApiEndpoint.Top>) => unknown)(
    ...Object.entries(operations).map(([name, operation]) => operationEndpoint(name, operation)),
  ) as never;

/**
 * What a client can rely on this server for. A flag an older server lacks reads as false; each
 * description says what a client does then.
 */
export const Capabilities = Schema.Struct({
  operations: Schema.Boolean.annotate({
    description:
      "Every catalog operation is served at its catalog path under /api. Without it, a client runs the engine in-process (decision 0002).",
  }),
  mcp: Schema.Boolean.annotate({
    description:
      "MCP over streamable HTTP at /mcp. Without it, an agent runs `octo mcp` over stdio.",
  }),
  openapi: Schema.Boolean.annotate({
    description:
      "The API's OpenAPI document at /api/openapi.json. Without it, a client that is not written in TypeScript has no generated schema.",
  }),
});
export type Capabilities = typeof Capabilities.Type;

export const Health = Schema.Struct({
  version: Schema.String,
  capabilities: Capabilities,
});
export type Health = typeof Health.Type;

const AddWorkspaceInput = Schema.Struct({
  // Relative paths would resolve against the server's own working directory.
  root: Schema.String.pipe(
    Schema.check(Schema.isPattern(/^\//, { message: "Use an absolute folder path" })),
  ),
  name: Schema.optionalKey(Schema.String),
  key: Schema.optionalKey(WorkspaceKey),
});

const errors = <const List extends ReadonlyArray<Schema.Top>>(...list: List) =>
  list.map((error) => wireError(error)) as unknown as { [K in keyof List]: WireError<List[K]> };

const inWorkspace = { workspace: RegisteredWorkspace };

const ChangeEvent = Schema.Struct({
  event: Schema.Literal("change"),
  data: Schema.fromJsonString(WorkspaceChange),
});

/** Sent when the stream opens, so the browser sees it open, and every 25 s to keep it open. */
const PingEvent = Schema.Struct({ event: Schema.Literal("ping"), data: Schema.Literal("") });

/** The endpoints the apps need that are not operations: setup, the board's data and its files. */
export class AppGroup extends HttpApiGroup.make("app").add(
  HttpApiEndpoint.get("health", "/health", { success: Health }),
  HttpApiEndpoint.get("connection", "/connection", {
    success: Schema.Struct({ url: Schema.String, mcpUrl: Schema.String }),
  }),
  HttpApiEndpoint.get("folders", "/folders", {
    query: {
      path: Schema.optionalKey(Schema.String).annotate({
        description: "An absolute folder; the server's home folder when omitted",
      }),
    },
    success: FolderListing,
    error: errors(InvalidRequest, StorageError),
  }),
  HttpApiEndpoint.post("add_workspace", "/workspaces", {
    payload: AddWorkspaceInput,
    success: WorkspaceInfo,
    error: errors(InvalidRequest, StorageError),
  }),
  HttpApiEndpoint.delete("remove_workspace", "/workspaces/:workspace", {
    params: inWorkspace,
    success: Schema.Struct({ removed: Schema.String }),
    error: errors(WorkspaceNotFound, StorageError),
  }),
  HttpApiEndpoint.get("snapshot", "/workspaces/:workspace", {
    params: inWorkspace,
    success: WorkspaceSnapshot,
    error: errors(WorkspaceNotFound, StorageError),
  }),
  HttpApiEndpoint.put("reorder_statuses", "/workspaces/:workspace/statuses/order", {
    params: inWorkspace,
    payload: ReorderStatusesInput,
    success: Schema.Array(StatusDefinition),
    error: errors(WorkspaceNotFound, InvalidRequest, StorageError),
  }),
  HttpApiEndpoint.post("fix_all", "/workspaces/:workspace/diagnostics/fix-all", {
    params: inWorkspace,
    success: FixResult,
    error: errors(WorkspaceNotFound, StorageError),
  }),
  // The request body is the file; a taken name gets -2, -3, and the reply says which.
  HttpApiEndpoint.put("upload_attachment", "/workspaces/:workspace/tasks/:id/files/:path", {
    params: {
      ...inWorkspace,
      id: Schema.String,
      path: Schema.String.annotate({
        description: "Where to save it in the task folder, one percent-encoded segment",
      }),
    },
    payload: HttpApiSchema.StreamUint8Array({ maxBytes: MAX_ATTACHMENT_BYTES }),
    success: Schema.Struct({ path: Schema.String }),
    error: errors(
      WorkspaceNotFound,
      TaskNotFound,
      InvalidRequest,
      AttachmentTooLarge,
      StorageError,
    ),
  }),
  HttpApiEndpoint.get("events", "/events", {
    success: HttpApiSchema.StreamSse({ events: Schema.Union([ChangeEvent, PingEvent]) }),
  }),
) {}

/** Turns a request that does not match its schema into an `InvalidRequest` with the reason. */
export class Validation extends HttpApiMiddleware.Service<Validation>()("octodo/Validation", {
  error: wireError(InvalidRequest),
}) {}

/** Everything under `/api` for a set of operations: the server serves the catalog and its plugins'. */
export const makeApi = <const Ops extends Record<string, Operation>>(operations: Ops) =>
  HttpApi.make("octodo")
    .add(operationsGroup(operations))
    .add(AppGroup)
    .middleware(Validation)
    .annotate(HttpApi.ParseOptions, { errors: "all" })
    .prefix("/api");

/**
 * The API a server serves for a set of operations, any plugins' by default. A plugin's web half
 * types its client from its own: `createClient<ServedApi<typeof shared.operations>>`.
 */
export type ServedApi<Ops extends Record<string, Operation> = Record<string, Operation>> =
  ReturnType<typeof makeApi<Ops>>;

/** Everything under `/api` for the catalog's operations: what clients are typed from. */
export class Api extends makeApi(catalog) {}
